import"./hoisted.h7flrgbf.js";const t=document.getElementById("contact-form"),n=document.getElementById("success-msg");t?.addEventListener("submit",async a=>{a.preventDefault();const e=t.querySelector('button[type="submit"]');e.disabled=!0,e.textContent="Enviando…";try{(await fetch(t.action,{method:"POST",body:new FormData(t),headers:{Accept:"application/json"}})).ok?(t.style.display="none",n&&n.classList.add("visible")):(e.disabled=!1,e.textContent="Enviar mensaje →",alert("Hubo un error al enviar. Por favor intenta de nuevo."))}catch{e.disabled=!1,e.textContent="Enviar mensaje →",alert("Sin conexión. Por favor intenta de nuevo.")}});
